     1	// Emits Orca's platforms.linux keybinding overrides: every action's macOS
     2	// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
     3	// Super on Linux -- and no Ctrl- or Alt-only chord, so emacs keys reach the
     4	// terminal. See orca.nix.
     5	//
     6	//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json> [pinned.json]
     7	//
     8	// pinned.json maps action ids to bindings that win over all of the above.
     9	//
    10	// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
    11	// facade its comment promises) for the definitions, normalisation and the
    12	// conflict check, so a version bump regenerates the table instead of
    13	// silently drifting from it.
    14	const fs = require('fs');
    15	const path = require('path');
    16	
    17	const [shared, chordsFile, pinnedFile] = process.argv.slice(2);
    18	const kb = require(path.resolve(shared, 'keybindings.js'));
    19	
    20	// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
    21	// "Cmd+Shift+W", Hyprland's modifier and keysym aliases included (keysyms
    22	// case-insensitively, as Hyprland reads them). Mouse, switch and media binds,
    23	// and the few keys Orca has no chord for (NO_CHORD), are skipped. Anything
    24	// else that does not translate fails the build: an unknown name may be an
    25	// Orca chord spelled another way, and guessing "harmless" ships a dead key.
    26	const MODS = {
    27	  SUPER: 'Cmd', WIN: 'Cmd', LOGO: 'Cmd', MOD4: 'Cmd', META: 'Cmd',
    28	  CTRL: 'Ctrl', CONTROL: 'Ctrl',
    29	  ALT: 'Alt', MOD1: 'Alt',
    30	  SHIFT: 'Shift',
    31	};
    32	const KEYS = {
    33	  return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown',
    34	  grave: 'Backquote', apostrophe: 'Quote',
    35	  prior: 'PageUp', next: 'PageDown', page_up: 'PageUp', page_down: 'PageDown',
    36	  kp_add: 'NumpadAdd', kp_subtract: 'NumpadSubtract',
    37	};
    38	const NO_CHORD = new Set(['print', 'scroll_lock', 'pause', 'sys_req', 'menu']);
    39	// Hyprland matches a bind on the unshifted keysym, but Orca matches the key
    40	// the press produced: Shift+= arrives as "+", which Orca names Plus, and
    41	// Shift+- as Underscore. Every other punctuation key Orca matches by its
    42	// unshifted name under Shift (probed against keybindingMatchesInput).
    43	const SHIFTED = { Equal: 'Plus', Minus: 'Underscore' };
    44	const taken = new Set();
    45	for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
    46	  if (typeof chord !== 'string') throw new Error(`Hyprland bind with a non-string key: ${JSON.stringify(chord)}`);
    47	  const parts = chord.split('+').map((s) => s.trim());
    48	  const key = parts.pop();
    49	  if (/^(mouse[:_]|xf86)/i.test(key) || chord.startsWith('switch:')) continue;
    50	  if (/^code:/.test(key)) {
    51	    // Which key a keycode is depends on the layout; there is no Orca name to check.
    52	    throw new Error(`Hyprland bind "${chord}" is a keycode bind; bind it by keysym so Orca's chords can be checked`);
    53	  }
    54	  const mods = parts.map((p) => MODS[p.toUpperCase()]);
    55	  if (!mods.every(Boolean)) throw new Error(`unknown modifier in Hyprland bind "${chord}"`);
    56	  // Bare keys too: Orca's few bare chords (F7, Delete) can be Hyprland's.
    57	  if (NO_CHORD.has(key.toLowerCase())) continue;
    58	  const n = kb.normalizeKeybindingWithOptions([...mods, KEYS[key.toLowerCase()] ?? key].join('+'), {
    59	    allowBareKeybindings: true,
    60	    allowShiftOnlyKeybindings: true,
    61	  });
    62	  if (!n.ok) {
    63	    throw new Error(`cannot translate Hyprland bind "${chord}" (${n.error}); map its key in KEYS, or NO_CHORD if Orca has none`);
    64	  }
    65	  taken.add(n.value);
    66	  const k = n.value.split('+').pop();
    67	  if (n.value.includes('Shift+') && SHIFTED[k]) taken.add(n.value.replace(/[^+]+$/, SHIFTED[k]));
    68	}
    69	// A digit-index action's one binding stands for its whole 1-9 family.
    70	const isTaken = (id, binding) =>
    71	  kb.isDigitIndexActionId(id)
    72	    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
    73	    : taken.has(binding);
    74	
    75	const overrides = {};
    76	for (const def of kb.KEYBINDING_DEFINITIONS) {
    77	  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
    78	    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
    79	    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
    80	    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
    81	    return n.value;
    82	  });
    83	  const free = mac.filter((b) => !isTaken(def.id, b));
    84	  if (free.length < mac.length) {
    85	    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
    86	  }
    87	  // Every chord taken leaves the action unbound -- not on its Linux default,
    88	  // which is a Ctrl chord the terminal would lose.
    89	  overrides[def.id] = free;
    90	}
    91	
    92	// Ctrl and Meta are the terminal's: emacs, readline. Any chord with Ctrl or
    93	// Alt and no Super goes -- the Mac table's own (Ctrl+1..9 tab select, Alt+Z
    94	// word wrap) as much as Linux defaults left standing (Alt+Shift+D split).
    95	// Tab cycling stays: terminals cannot send Ctrl+Tab or Ctrl+PageUp/Down.
    96	const TERMINAL_CANNOT_SEND = new Set(['Ctrl+Tab', 'Ctrl+PageUp', 'Ctrl+PageDown']);
    97	const takesFromTerminal = (b) => {
    98	  const mods = b.split('+').slice(0, -1);
    99	  return !mods.includes('Cmd') && mods.some((m) => m === 'Ctrl' || m === 'Alt' || m === 'Mod') && !TERMINAL_CANNOT_SEND.has(b);
   100	};
   101	for (const def of kb.KEYBINDING_DEFINITIONS) {
   102	  const effective = overrides[def.id] ?? kb.getDefaultBindings(def, 'linux');
   103	  const kept = effective.filter((b) => !takesFromTerminal(b));
   104	  if (kept.length < effective.length) {
   105	    console.error(`${def.id}: ${effective.filter(takesFromTerminal).join(', ')} is the terminal's`);
   106	  }
   107	  overrides[def.id] = kept;
   108	}
   109	
   110	// Pinned bindings (orca.nix) win over everything above.
   111	if (pinnedFile) {
   112	  for (const [id, bindings] of Object.entries(JSON.parse(fs.readFileSync(pinnedFile, 'utf8')))) {
   113	    if (!kb.getKeybindingDefinition(id)) throw new Error(`pinned: unknown Orca action "${id}"`);
   114	    overrides[id] = bindings.map((b) => {
   115	      const n = kb.normalizeKeybindingWithOptions(b, kb.normalizeOptionsForAction(id));
   116	      if (!n.ok) throw new Error(`pinned: ${id}: ${b}: ${n.error}`);
   117	      if (isTaken(id, n.value)) throw new Error(`pinned: ${id}: ${n.value} is Hyprland's`);
   118	      return n.value;
   119	    });
   120	  }
   121	}
   122	
   123	// Nothing to say where the result is Orca's own Linux default.
   124	for (const def of kb.KEYBINDING_DEFINITIONS) {
   125	  if (JSON.stringify(overrides[def.id]) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) delete overrides[def.id];
   126	}
   127	
   128	// Orca drops every action in a conflicting set at load, with only a line in
   129	// its diagnostics; fail the build instead.
   130	const conflicts = kb.findKeybindingConflicts('linux', overrides);
   131	if (conflicts.length > 0) {
   132	  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
   133	}
   134	process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);
diff --git a/orca.nix b/orca.nix
index 72e5e26b..cfae2c29 100644
--- a/orca.nix
+++ b/orca.nix
@@ -89,6 +89,84 @@ let
   # Extracted once, shared by the wrapper's extraInstallCommands below;
   # let bindings are recursive, so position in the block does not matter.
   appimageContents = pkgs.appimageTools.extract { inherit pname version src; };
+
+  # Mac-style shortcuts, the same Super-for-Cmd scheme as gtk's mac-bindings
+  # and ghostty's super+c/v in home.nix: Orca's own macOS defaults, with Cmd
+  # spelled out, which Orca binds to Super (event.metaKey) on Linux. The point
+  # is that Ctrl and Meta stay the terminal's -- emacs keys reach the shell --
+  # so no Ctrl- or Alt-only chord is left at all: not the Mac table's own
+  # (Ctrl+1..9 tab select, Alt+Z word wrap), not a Linux default. Ctrl+Tab and
+  # Ctrl+PageUp/Down stay; no terminal can send them.
+  #
+  # Generated from the app's own keybinding definitions at build time
+  # (nix/orca-mac-keybindings.js), so a version bump picks up new actions.
+  # Chords Hyprland binds would be dead keys, so those actions are unbound --
+  # on shiori 19 of them, Super+F (find) and Super+P (go to file) among them,
+  # plus Super+B/N/E, the digits, and their Shift forms. orcaPinned below
+  # rebinds the ones worth having elsewhere. The build log lists every one.
+  #
+  # A running Orca reads the file once; after a switch, restart it (or run its
+  # keybindings reload) for the new table to apply. Resetting a generated
+  # shortcut in Orca's settings re-applies the Mac chord at the next switch:
+  # Orca stores a reset, and a pick of its own Linux default, as the same
+  # deletion, so neither sticks -- set some other chord, or unbind, instead.
+  #
+  # Find goes on Ctrl+S, emacs' isearch, everywhere but the terminal; there
+  # C-s is the shell's own search, so terminal search is left unbound.
+  orcaPinned = {
+    "editor.find" = [ "Ctrl+S" ];
+    "browser.find" = [ "Ctrl+S" ];
+    "chat.find" = [ "Ctrl+S" ];
+    "settings.search" = [ "Ctrl+S" ];
+  };
+  hyprlandChords = let s = config.wayland.windowManager.hyprland.settings; in
+    lib.concatMap
+      (k: map (b: if builtins.isAttrs b && b ? _args then builtins.head b._args else b) s.${k})
+      # bind, bindl, binde, ...: the lists. `binds` is a config section, a set.
+      (builtins.filter (k: lib.hasPrefix "bind" k && builtins.isList s.${k}) (builtins.attrNames s));
+  macKeybindings = pkgs.runCommand "orca-mac-keybindings" {
+    nativeBuildInputs = [ pkgs.nodejs pkgs.asar pkgs.makeWrapper pkgs.jq ];
+  } ''
+    asar extract ${appimageContents}/resources/app.asar app
+    mkdir -p $out/share $out/bin
+    node ${./nix/orca-mac-keybindings.js} app/out/shared \
+      ${pkgs.writeText "hyprland-chords.json" (builtins.toJSON hyprlandChords)} \
+      ${pkgs.writeText "orca-pinned.json" (builtins.toJSON orcaPinned)} \
+      > $out/share/orca-mac-keybindings.json
+    # The merge runs Orca's conflict check on the merged file at activation,
+    # so the keybinding module (and its one sibling import) ships alongside.
+    mkdir -p $out/lib/shared
+    cp -r app/out/shared/keybindings.js app/out/shared/keybindings \
+      app/out/shared/tui-agent-display-names.js $out/lib/shared/
+    makeWrapper ${pkgs.nodejs}/bin/node $out/bin/orca-mac-keybindings \
+      --add-flags "${./nix/orca-mac-keybindings-merge.js} $out/lib/shared $out/share/orca-mac-keybindings.json"
+    # One real merge, so an Orca bump that moves an import or an export the
+    # merge uses fails here, not as a warning at every activation. The seed
+    # is a string (comma-list) value, so the shorthand parser runs too; it
+    # sits on a New-agent-tab action, unbound on every platform, so the
+    # table never claims it whatever Hyprland binds. The check is that every
+    # generated entry landed as generated, and the seed survived.
+    mkdir -p $TMPDIR/home/.orca
+    echo '{"version":1,"keybindings":{},"platforms":{"linux":{"tab.newAgent.claude":"Alt+F12, Alt+Shift+F12"}}}' \
+      > $TMPDIR/home/.orca/keybindings.json
+    HOME=$TMPDIR/home $out/bin/orca-mac-keybindings 2> merge.err
+    if [ -s merge.err ] \
+       || ! jq -e --slurpfile o $out/share/orca-mac-keybindings.json '
+            .platforms.linux as $l
+            | ($o[0] | to_entries | all(.value == $l[.key]))
+              and $l["tab.newAgent.claude"] == "Alt+F12, Alt+Shift+F12"' \
+            $TMPDIR/home/.orca/keybindings.json >/dev/null \
+       || [ ! -s $TMPDIR/home/.orca/keybindings.nix-owned.json ]; then
+      cat merge.err >&2; echo "orca: build-time merge did not apply the table" >&2; exit 1
+    fi
+  '';
+  # ~/.orca/keybindings.json is Orca's read-write state: its settings UI saves
+  # into the same platforms.linux section, by atomic rename, so a home.file
+  # symlink would be replaced on the first edit. So the generated keys are
+  # merged into whatever Orca last wrote, owning only what the last merge
+  # wrote (a sidecar records it), and a UI edit outranks them -- the rules
+  # are at the top of nix/orca-mac-keybindings-merge.js.
+  # tests/orca-mac-keybindings.sh.
 in
 {
   home.packages =
@@ -98,4 +176,9 @@ in
     # same reason parsec gets it.
       (config.lib.nixGL.wrap orca)
     ];
+
+  home.activation.orcaMacKeybindings = lib.mkIf (!isDarwin && isDesktop)
+    (lib.hm.dag.entryAfter [ "writeBoundary" ] ''
+      $DRY_RUN_CMD ${macKeybindings}/bin/orca-mac-keybindings
+    '');
 }

